priority:
: it is uniform across a sitemap by construction here, and a
  uniform priority carries exactly as much information as none at all. 
  is the attribute search engines actually read, so it is present on every entry
  and comes from the `date` each list already declares.
#}
{% set ns = namespace(seen=[]) %}


    {{ SITEURL }}/aporia/
    {{ APORIA | map(attribute='date') | max }}
    monthly

{% for item in APORIA + PROJECTS + NAGEL_DASHBOARDS %}
{% set url = item.url.split('#')[0] %}
{% if url and url not in ns.seen and not item.noindex %}
{% set ns.seen = ns.seen + [url] %}

    {{ SITEURL }}{{ url }}
{% if item.date %}    {{ item.date }}
{% endif %}    monthly

{% endif %}
{% endfor %}
